{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "あぁどうしようもないほどに",
        "私に蠢く獣",
        "水面浮かんで浮かんでは消えるあぶく"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "あぁどうしようもなく悲しい",
        "私を動かす獣",
        "トートロジー握った手のあぶく"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "過ぎ去る雲を思うより",
        "遥かへ遠吠え",
        "息継ぐ暇もないほど",
        "苦しいあれで"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "悠々悠々夢を焼け",
        "魂の白い白い色で",
        "喜びの火に火をつけたいだけ",
        "想像は少しの泡銭",
        "冷めない言葉の両手で",
        "燃え尽きないものを数えて",
        "掬いたいだけ"
      ]
    }
  ],
  "section": "V2",
  "phrases": [
    {
      "id": "V2-01",
      "ja": "あぁどうしようもなく悲しい",
      "budget": {
        "min": 8,
        "max": 8
      },
      "pattern": [
        1,
        4,
        3
      ]
    },
    {
      "id": "V2-02",
      "ja": "私を動かす獣",
      "budget": {
        "min": 8,
        "max": 8
      },
      "pattern": [
        3,
        5
      ]
    },
    {
      "id": "V2-03",
      "ja": "トートロジー握った手のあぶく",
      "budget": {
        "min": 11,
        "max": 11
      },
      "pattern": [
        6,
        5
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "啊，无可奈何地悲伤"
        },
        {
          "id": "V2-02",
          "zh": "驱动我的野兽"
        },
        {
          "id": "V2-03",
          "zh": "同义反复握住的手中的泡沫"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "沉 胸口有雨 落不尽"
        },
        {
          "id": "V2-02",
          "zh": "手心里 有兽在低吼"
        },
        {
          "id": "V2-03",
          "zh": "念头绕回原点 泡沫攥成空"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "啊，无可奈何的悲伤"
        },
        {
          "id": "V2-02",
          "zh": "驱使我内心的野兽"
        },
        {
          "id": "V2-03",
          "zh": "同义反复紧握手中的泡沫"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "啊 按不住的 这悲伤"
        },
        {
          "id": "V2-02",
          "zh": "推着我 不肯停的兽"
        },
        {
          "id": "V2-03",
          "zh": "绕圈的那句话 握碎成泡沫"
        }
      ]
    },
    {
      "label": "E",
      "phrases": [
        {
          "id": "V2-01",
          "zh": "啊 无处安放的伤悲"
        },
        {
          "id": "V2-02",
          "zh": "驱使我前行的兽"
        },
        {
          "id": "V2-03",
          "zh": "同义反复握紧的 手中泡影"
        }
      ]
    }
  ]
}

